/// Whether `host` is a domain name (dot-separated letter-digit-hyphen labels),
/// optionally followed by `:port`, and not an IP address.
fn is_domain_host(host: &str) -> bool {
    let (name, port) = match host.rsplit_once(':') {
        Some((name, port)) => (name, Some(port)),
        None => (host, None),
    };
    if port.is_some_and(|port| port.parse::<u16>().is_err()) {
        return false;
    }
    let labels_ok = !name.is_empty()
        && name.split('.').all(|label| {
            !label.is_empty()
                && label.len() <= 63
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-')
        });
    // A URL parser reads numeric hosts (127.0.0.1, 2130706433, 0x7f000001) as IPv4 addresses.
    labels_ok && matches!(url::Url::parse(&format!("https://{name}/")).ok().as_ref().and_then(url::Url::host), Some(url::Host::Domain(_)))
}

/// `segment` with every byte that is not allowed literally in a URL path
/// segment (RFC 3986 `pchar`) percent-encoded.
fn percent_encode_segment(segment: &str) -> String {
    let mut out = String::with_capacity(segment.len());
    for b in segment.bytes() {
        if b.is_ascii_alphanumeric() || b"-._~!$&'()*+,;=:@".contains(&b) {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

