    labels_ok && matches!(url::Url::parse(&format!("https://{name}/")).ok().as_ref().and_then(url::Url::host), Some(url::Host::Domain(_)))
}

/// `segment` with every byte that is not allowed literally in a URL path
/// segment (RFC 3986 `pchar`) percent-encoded.
fn percent_encode_segment(segment: &str) -> String {
    let mut out = String::with_capacity(segment.len());
    for b in segment.bytes() {
        if b.is_ascii_alphanumeric() || b"-._~!$&'()*+,;=:@".contains(&b) {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

