//! Status-change webhooks.
//!
//! When a credential's status flips ([`crate::status::revoke_credential`]),
//! [`Notifier::notify`] sends the change to the relying parties that
//! subscribed to the issuing tenant's changes. A subscription is a tenant
//! setting of kind [`WEBHOOK_KIND`] whose value holds the endpoint `url`.
//!
//! Deliveries run concurrently, at most [`MAX_CONCURRENT_DELIVERIES`] at a
//! time, each bounded by [`DELIVERY_TIMEOUT`], and the whole change by
//! [`DISPATCH_BUDGET`]. There are no retries: every subscriber gets exactly
//! one [`DeliveryEvent`] in the [`DeliverySink`], and one that is not
//! delivered, including one not reached before the budget ran out, is
//! recorded as [`Outcome::Failed`].
//!
//! The canary is a platform subscription on the instance's loopback that
//! receives every change, sent after the subscriber lookup through the same
//! transport as the change's subscribers. [`Notifier::canary_healthy`] is the
//! notifier's health check: green only if, for the most recent change, the
//! canary acknowledged and every subscriber was looked up and attempted
//! within the budget. A relying party's own failure is reported in its
//! delivery event, not in the health check.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use serde_json::json;
use tokio::task::JoinSet;
use tokio::time::{timeout_at, Instant};

use crate::settings::{Setting, SettingsStore};
use crate::status::StatusChange;
use crate::webhook::WebhookTransport;

/// How long one status change may take, lookup and fan-out together. The
/// deployed function is killed at 10 s from the start of its invocation
/// (`timeout_seconds` in the deployment configuration); this leaves room for
/// the invocation's start-up and for recording what was not delivered.
pub const DISPATCH_BUDGET: Duration = Duration::from_secs(7);

/// How long one delivery may take, connect included (the platform's own
/// connect timeout is 2 s). An endpoint that accepts the connection and never
/// answers is given up on after this.
pub const DELIVERY_TIMEOUT: Duration = Duration::from_secs(3);

/// Deliveries in flight at once for one change. With [`DELIVERY_TIMEOUT`]
/// inside [`DISPATCH_BUDGET`], two full rounds of non-answering endpoints
/// (32) still leave every subscriber attempted; healthy endpoints go through
/// at 16 per round trip. Across the 20 instances the deployment allows, that
/// is at most 320 connections through the shared NAT gateways.
pub const MAX_CONCURRENT_DELIVERIES: usize = 16;

/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
/// The canary receiver the platform operates on the instance's loopback,
/// behind the same outbound client as the subscribers' calls.
pub const CANARY_URL: &str = "http://127.0.0.1/webhooks/canary";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Subscription {
    pub id: String,
    pub url: String,
}

impl Subscription {
    pub fn canary() -> Self {
        Subscription { id: CANARY_ID.to_string(), url: CANARY_URL.to_string() }
    }

    /// The subscription a webhook setting describes; its id is the part of
    /// the key after `webhook/`.
    pub fn from_setting(setting: &Setting) -> Option<Self> {
        let url = setting.value.get("url")?.as_str()?;
        let id = setting.key.strip_prefix("webhook/").unwrap_or(&setting.key);
        Some(Subscription { id: id.to_string(), url: url.to_string() })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Outcome {
    /// The endpoint acknowledged the call (2xx).
    Delivered { status: u16 },
    /// The endpoint refused the call or could not be reached.
    Failed { reason: String },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeliveryEvent {
    pub tenant: String,
    pub subscription: String,
    pub outcome: Outcome,
}

/// Where delivery outcomes go (metrics, audit).
pub trait DeliverySink: Send + Sync {
    fn record(&self, event: DeliveryEvent);
}

/// Keeps every event in memory.
#[derive(Debug, Default)]
pub struct MemorySink {
    events: Mutex<Vec<DeliveryEvent>>,
}

impl MemorySink {
    pub fn events(&self) -> Vec<DeliveryEvent> {
        self.events.lock().unwrap().clone()
    }
}

impl DeliverySink for MemorySink {
    fn record(&self, event: DeliveryEvent) {
        self.events.lock().unwrap().push(event);
    }
}

/// The JSON body sent for `change`.
pub fn payload(change: &StatusChange) -> Vec<u8> {
    json!({
        "type": "credential.status_changed",
        "credential_id": change.credential_id,
        "issuer": change.issuer,
        "status_list": change.status_list,
        "status_index": change.status_index,
        "revoked": change.revoked,
    })
    .to_string()
    .into_bytes()
}

pub struct Notifier {
    settings: Arc<SettingsStore>,
    transport: Arc<dyn WebhookTransport>,
    sink: Arc<dyn DeliverySink>,
    /// Subscribers to every tenant's changes.
    platform: Vec<Subscription>,
    canary_ok: AtomicBool,
}

impl Notifier {
    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
        Notifier {
            settings,
            transport,
            sink,
            platform: vec![Subscription::canary()],
            canary_ok: AtomicBool::new(false),
        }
    }

    /// Adds a subscriber to every tenant's changes.
    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
        self.platform.push(subscription);
        self
    }

    /// Whether the most recent change was looked up, attempted for every
    /// subscriber within the budget, and acknowledged by the canary.
    pub fn canary_healthy(&self) -> bool {
        self.canary_ok.load(Ordering::SeqCst)
    }

    /// Sends `change` to every subscriber of the issuing tenant and to the
    /// platform subscribers.
    pub async fn notify(&self, change: &StatusChange) {
        let tenant = change.issuer.as_str();
        let deadline = Instant::now() + DISPATCH_BUDGET;

        let Ok(subscriptions) = timeout_at(deadline, self.subscriptions(tenant)).await else {
            eprintln!("notifier: {tenant}: subscribers for {} not read within {DISPATCH_BUDGET:?}", change.credential_id);
            self.canary_ok.store(false, Ordering::SeqCst);
            return;
        };
        let targets: Vec<Subscription> = self.platform.iter().cloned().chain(subscriptions).collect();
        let healthy = self.fan_out(tenant, &targets, payload(change).into(), deadline).await;
        self.canary_ok.store(healthy, Ordering::SeqCst);
    }

    /// The tenant's webhook subscriptions, through the `tenant-kind` index.
    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
        self.settings.query_kind(tenant, WEBHOOK_KIND).await.iter().filter_map(Subscription::from_setting).collect()
    }

    /// Delivers `body` to every target and records one event per target.
    /// `true` if every target was attempted before `deadline` and the canary
    /// acknowledged.
    async fn fan_out(&self, tenant: &str, targets: &[Subscription], body: Arc<[u8]>, deadline: Instant) -> bool {
        let mut done = vec![false; targets.len()];
        let mut canary_delivered = false;
        let mut next = 0;
        let mut in_flight = JoinSet::new();
        let exhausted = loop {
            while in_flight.len() < MAX_CONCURRENT_DELIVERIES && next < targets.len() {
                let (transport, url, body, index) = (self.transport.clone(), targets[next].url.clone(), body.clone(), next);
                in_flight.spawn(async move { (index, deliver(transport.as_ref(), &url, &body).await) });
                next += 1;
            }
            match timeout_at(deadline, in_flight.join_next()).await {
                Ok(Some(Ok((index, outcome)))) => {
                    let sub = &targets[index];
                    if sub.id == CANARY_ID {
                        canary_delivered = matches!(outcome, Outcome::Delivered { .. });
                    }
                    done[index] = true;
                    self.record(tenant, sub, outcome);
                }
                Ok(Some(Err(error))) => eprintln!("notifier: {tenant}: delivery task failed: {error}"),
                Ok(None) => break false,
                Err(_) => break true,
            }
        };
        in_flight.abort_all();

        let reason = if exhausted { format!("not delivered within {DISPATCH_BUDGET:?}") } else { "delivery task failed".to_string() };
        for (sub, _) in targets.iter().zip(&done).filter(|(_, done)| !**done) {
            self.record(tenant, sub, Outcome::Failed { reason: reason.clone() });
        }
        canary_delivered && done.iter().all(|d| *d)
    }

    fn record(&self, tenant: &str, sub: &Subscription, outcome: Outcome) {
        self.sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
    }
}

/// POSTs `body` to `url`, giving up after [`DELIVERY_TIMEOUT`].
async fn deliver(transport: &dyn WebhookTransport, url: &str, body: &[u8]) -> Outcome {
    match tokio::time::timeout(DELIVERY_TIMEOUT, transport.post(url, body)).await {
        Ok(Ok(status)) if (200..300).contains(&status) => Outcome::Delivered { status },
        Ok(Ok(status)) => Outcome::Failed { reason: format!("HTTP {status}") },
        Ok(Err(error)) => Outcome::Failed { reason: error.to_string() },
        Err(_) => Outcome::Failed { reason: format!("no response within {DELIVERY_TIMEOUT:?}") },
    }
}

