/// inside [`DISPATCH_BUDGET`], two full rounds of non-answering endpoints
/// (32) still leave every subscriber attempted; healthy endpoints go through
/// at 16 per round trip. Across the 20 instances the deployment allows, that
/// is at most 320 connections through the shared NAT gateways.
pub const MAX_CONCURRENT_DELIVERIES: usize = 16;

/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
/// The canary receiver the platform operates on the instance's loopback,
/// behind the same outbound client as the subscribers' calls.
pub const CANARY_URL: &str = "http://127.0.0.1/webhooks/canary";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Subscription {
    pub id: String,
    pub url: String,
}

